# Private evaluation kernel generated by scripts/kaggle_eval/make_kernel.py — runs our submission on
# the real scorer hardware (4x L4, vLLM TP=4, 32k context) with the official harness, mirroring
# scripts/inference.py settings from HARNESS_README (compaction interval 5, threshold 14336).
import asyncio
import base64
import glob
import io
import json
import os
import shutil
import subprocess
import sys
import time
import zipfile
from pathlib import Path

RUN_NAME = "__RUN_NAME__"
TASK_IDS = __TASK_IDS__
CONCURRENCY = __CONCURRENCY__
SUBMISSION_B64 = "__SUBMISSION_B64__"

os.environ.update({
    "LITELLM_LOCAL_MODEL_COST_MAP": "True", "TRANSFORMERS_NO_TF": "1", "VLLM_WORKER_MULTIPROC_METHOD": "spawn",
    "VLLM_MEMORY_PROFILER_ESTIMATE_CUDAGRAPHS": "1", "VLLM_ENGINE_READY_TIMEOUT_S": "1200",
    "VLLM_NO_USAGE_STATS": "1", "OTEL_SDK_DISABLED": "true", "PYTORCH_CUDA_ALLOC_CONF": "expandable_segments:True",
})
T0 = time.time()


def find_dir(*patterns):
    for p in patterns:
        hits = sorted(glob.glob(p))
        if hits:
            return Path(hits[0])
    raise FileNotFoundError(patterns)


WHEELHOUSE = find_dir("/kaggle/input/datasets/metric/gemma-4-developer-agent-wheelhouse",
                      "/kaggle/input/*/gemma-4-developer-agent-wheelhouse", "/kaggle/input/gemma-4-developer-agent-wheelhouse")
DATA = find_dir("/kaggle/input/competitions/gemma-4-developer-agent", "/kaggle/input/gemma-4-developer-agent")
MODEL = find_dir("/kaggle/input/models/google/gemma-4/*/gemma-4-31b-it-qat-w4a16-ct/*",
                 "/kaggle/input/gemma-4/*/gemma-4-31b-it-qat-w4a16-ct/*")
WORK = Path("/kaggle/working")

# --- install wheelhouse exactly like the official getting-started notebook ---
for pth in glob.glob("/usr/local/lib/python*/dist-packages/*cutlass*.pth") + glob.glob("/usr/local/lib/python*/site-packages/*cutlass*.pth"):
    try:
        os.unlink(pth)
    except OSError:
        pass
tmp_whl = Path("/tmp/wheelhouse")
tmp_whl.mkdir(parents=True, exist_ok=True)
for w in WHEELHOUSE.glob("*.whl"):
    if "cutlass" in w.name.lower():
        continue
    name = w.name.replace("cu128", "+cu128") if ("cu128" in w.name and "+" not in w.name) else w.name
    if not (tmp_whl / name).exists():
        os.symlink(w, tmp_whl / name)
subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-deps", "--force-reinstall",
                *sorted(str(w) for w in tmp_whl.glob("*.whl"))], check=True)
print(f"[{time.time() - T0:.0f}s] wheels installed", flush=True)

# Test-only packages the scorer's sandbox image has but the Kaggle notebook image lacks
# (fastapi tests import inline_snapshot/dirty_equals; requests tests need pytest-httpbin).
TEST_WHEELS = sorted(glob.glob("/kaggle/input/*/gemma-rl-test-wheels") + glob.glob("/kaggle/input/datasets/*/gemma-rl-test-wheels")
                     + glob.glob("/kaggle/input/gemma-rl-test-wheels"))
if TEST_WHEELS:
    r = subprocess.run([sys.executable, "-m", "pip", "install", "-q", "--no-index", f"--find-links={TEST_WHEELS[0]}",
                        "inline-snapshot", "dirty-equals", "pytest-httpbin", "httpbin", "trustme", "pytest-mock"],
                       capture_output=True, text=True)
    print("test wheels:", r.returncode, r.stderr[-500:], flush=True)
else:
    print("WARNING: gemma-rl-test-wheels dataset not mounted", flush=True)

# --- unpack our submission ---
AGENT_DIR = WORK / "submission"
shutil.rmtree(AGENT_DIR, ignore_errors=True)
zipfile.ZipFile(io.BytesIO(base64.b64decode(SUBMISSION_B64))).extractall(AGENT_DIR)

import litellm  # noqa: E402
import torch  # noqa: E402
import yaml  # noqa: E402
from adk_submission import VllmConfig, VllmServer, discover_adapters  # noqa: E402
from google.adk.agents.context_cache_config import ContextCacheConfig  # noqa: E402
from google.adk.apps._configs import EventsCompactionConfig  # noqa: E402
from swegemma.config import ALLOWED_ADAPTER_EXTENSIONS, EvalConfig, build_submission_limits  # noqa: E402
from swegemma.evaluate import Evaluator  # noqa: E402
from swegemma.models.discovery import validate_single_declared_model  # noqa: E402

litellm.drop_params = True
declared = validate_single_declared_model(AGENT_DIR)
adapters = discover_adapters(str(AGENT_DIR), adapter_extensions=ALLOWED_ADAPTER_EXTENSIONS)
ngpu = torch.cuda.device_count()
server = VllmServer(VllmConfig(
    model=str(MODEL), port=8000, host="127.0.0.1", tool_call_parser="gemma4", reasoning_parser="gemma4",
    max_model_len=32768, dtype="bfloat16", gpu_memory_utilization=0.80, enable_auto_tool_choice=True,
    enable_lora=True, max_loras=8, max_lora_rank=128, tensor_parallel_size=4 if ngpu >= 4 else max(1, ngpu),
    default_chat_template_kwargs={"enable_thinking": True}, startup_timeout=60 * 25,
), adapter_manifest=adapters)
server.start()
print(f"[{time.time() - T0:.0f}s] vLLM up on {ngpu} GPUs", flush=True)
models = server.create_model_registry(aliases=[declared, "gemma-4-31b-it-qat-w4a16-ct"], model_prefix="openai/", api_key="EMPTY")

raw = yaml.safe_load((AGENT_DIR / "eval_config.yaml").read_text()) if (AGENT_DIR / "eval_config.yaml").exists() else {}
ev = (raw or {}).get("evaluation", raw or {})
limits, gen = build_submission_limits()
results_dir = WORK / "results" / RUN_NAME
cfg = EvalConfig(
    tasks_path=DATA / "tasks.jsonl", snapshots_dir=DATA / "snapshots", results_dir=results_dir,
    submission_dir=AGENT_DIR, models=models, sandbox="subprocess",
    timeout_seconds=int(ev.get("timeout_seconds", 300)), max_time_minutes=float(ev.get("max_time_minutes", 60)),
    max_tool_calls=int(ev.get("max_tool_calls", 100)),
    max_turns=int(ev["max_turns"]) if ev.get("max_turns") is not None else None,
    task_ids=TASK_IDS or None, limits=limits, generation_constraints=gen, adapter_manifest=adapters,
    context_cache_config=ContextCacheConfig(min_tokens=2048, ttl_seconds=1800, cache_intervals=10),
    events_compaction_config=EventsCompactionConfig(compaction_interval=5, overlap_size=2, token_threshold=14336, event_retention_size=5),
    graph_dir=str(DATA / "graphs"), embeddings_dir=str(DATA / "embeddings"), wheels_dir=DATA / "wheels",
    concurrency=CONCURRENCY, display_mode="quiet",
)
res = asyncio.run(Evaluator(cfg).run())
summary = {"run": RUN_NAME, "resolved": res.resolved, "total": res.total, "rate": res.resolution_rate,
           "wall_seconds": round(time.time() - T0), "concurrency": CONCURRENCY}
print(json.dumps(summary), flush=True)
(results_dir / "kernel_summary.json").write_text(json.dumps(summary, indent=1))
server.stop()
